sys_script_include.script:
function GetAllHoursRuleSetsForStore(vStore)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var Clone = x_snc_devtools.Clone;
	var GetCountryRecord = x_snc_devtools.GetCountryRecord;
	var GetRecord = x_snc_devtools.GetRecord;

	var grStore = GetStoreRecord(vStore);
	if (IsValidRecord(grStore) == false)
	{
		return false;
	}

	var aHoursRuleSets = [];

	var grHoursRuleSets = new GlideRecord('x_snc_stores_hours_rule_set');
	grHoursRuleSets.addQuery('store','=',grStore.sys_id);
	grHoursRuleSets.query();
	while (grHoursRuleSets.next())
	{
		var hoursruleset = Clone(grHoursRuleSets);
		aHoursRuleSets.push(hoursruleset);
	}

	var grCountry = GetCountryRecord(grStore.country);
	if (IsValidRecord(grCountry) == true)
	{
		var grHoursRuleSets = new GlideRecord('x_snc_stores_hours_rule_set');
		grHoursRuleSets.addQuery('country','=',grCountry.sys_id);
		grHoursRuleSets.addQuery('subdivision','=','');
		grHoursRuleSets.query();
		while (grHoursRuleSets.next())
		{
			var hoursruleset = Clone(grHoursRuleSets);
			aHoursRuleSets.push(hoursruleset);
		}

		var grSubdivision = GetRecord('x_snc_geodata_country_subdivision',grStore.subdivision);
		if (IsValidRecord(grSubdivision) == true)
		{
			var grHoursRuleSets = new GlideRecord('x_snc_stores_hours_rule_set');
			grHoursRuleSets.addQuery('country','=',grCountry.sys_id);
			grHoursRuleSets.addQuery('subdivision','=',grSubdivision.sys_id);
			grHoursRuleSets.query();
			while (grHoursRuleSets.next())
			{
				var hoursruleset = Clone(grHoursRuleSets);
				aHoursRuleSets.push(hoursruleset);
			}
		}		
	}

	return aHoursRuleSets;
}
